using System;using System.Data.SqlClient;
namespace Training.Manager{public partial class TraineeProgress:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string MID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(MID))Response.Redirect("~/Default.aspx");if(!IsPostBack)BindGrid();}
private void BindGrid(){string q="SELECT TA.TrainingID,TA.EmpID,EBM.EmpName,COUNT(DISTINCT SM.SessionID) TotalSessions,COUNT(DISTINCT CASE WHEN SA.AttendanceStatus IS NOT NULL THEN SM.SessionID END) SessionsWithAttendance,COUNT(DISTINCT CASE WHEN SA.AttendanceStatus='Present' THEN SM.SessionID END) PresentSessions,CAST(CASE WHEN COUNT(DISTINCT SM.SessionID)=0 THEN 0 ELSE COUNT(DISTINCT CASE WHEN SA.AttendanceStatus='Present' THEN SM.SessionID END)*100.0/COUNT(DISTINCT SM.SessionID) END AS DECIMAL(10,2)) AttendancePercent FROM TrainingAssignment TA INNER JOIN EmpBasicMaster EBM ON TA.EmpID=EBM.EmpID INNER JOIN TrainingDetails TD ON TA.TrainingID=TD.TrainingID INNER JOIN TrainingLocationMaster L ON TD.TrainingLocation=L.TrainingLocation INNER JOIN ManagerMaster M ON M.TrainingLocationID=L.TrainingLocationID INNER JOIN SessionMaster SM ON SM.TrainingID=TA.TrainingID LEFT JOIN SessionAttendance SA ON SA.SessionID=SM.SessionID AND SA.EmpID=TA.EmpID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y' AND TA.AssignmentStatus='Assigned'";var p=new System.Collections.Generic.List<SqlParameter>();p.Add(new SqlParameter("@ManagerID",MID));if(!string.IsNullOrWhiteSpace(txtTrainingID.Text)){q+=" AND TA.TrainingID=@TrainingID";p.Add(new SqlParameter("@TrainingID",txtTrainingID.Text.Trim()));}if(!string.IsNullOrWhiteSpace(txtSearch.Text)){q+=" AND (TA.EmpID LIKE @Search OR EBM.EmpName LIKE @Search)";p.Add(new SqlParameter("@Search","%"+txtSearch.Text.Trim()+"%"));}q+=" GROUP BY TA.TrainingID,TA.EmpID,EBM.EmpName ORDER BY TA.TrainingID,EBM.EmpName";gvProgress.DataSource=obj.GetDataTable(q,p.ToArray());gvProgress.DataBind();}protected void btnSearch_Click(object s,EventArgs e){BindGrid();}}}